Certainly! Below is a simple Go program that reads the contents of a given Go source file, parses the struct definition within it, and generates an Avro schema for that struct.

```go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"

	"github.com/blang/semver/v4"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <struct_name> <source_file>")
		os.Exit(1)
	}

	structName := os.Args[1]
	sourceFile := os.Args[2]

	// Parse the source file
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, sourceFile, nil, parser.ParseComments)
	if err != nil {
		panic(err)
	}

	// Check if the struct exists
	for _, decl := range fset.File.Decls {
		if ast.IsExportedDecl(decl) && decl.Name.Name == structName {
			// Get the fields of the struct
			fields := make(map[string]ast.Field)
			for i := 0; i < len(file.Decls); i++ {
				if ast.IsExportedDecl(file.Decls[i]) {
					field := file.Decls[i].(*ast.Field)
					fields[field.Name.Text()] = field
				}
			}

			// Generate Avro schema
			schema, _ := genAvroSchema(fields)
			fmt.Printf("%s\n", schema)
		}
	}
}

func genAvroSchema(fields map[string]ast.Field) (string, error) {
	var types []interface{}
	for fieldName, field := range fields {
		typeDef := fmt.Sprintf("\"%s\": %v", fieldName, field.Type)
		types = append(types, typeDef)
	}

	return fmt.Sprintf(`{"type": "record", "name": "%s", "fields": [%s]}`, structName, strings.Join(types, ",\n")), nil
}
```

### How to Use This Program:
1. Save this code into a file called `script.go`.
2. Compile the program using `go build -o script script.go`.
3. Run the compiled program with two arguments: the name of your struct and the path to the Go source file containing the struct definition.
   ```sh
   ./script myStruct MySourceFile.go
   ```
4. The program will print out the generated Avro schema for the specified struct.

### Example Usage:

Assume you have a Go source file `example.go` which defines a struct as follows:

```go
package example

type Person struct {
	Name string `json:"name"`
 Age int    `json:"age"`
}
```

Running the program would produce an Avro schema like:

```json
{
  "type": "record",
  "name": "Person",
  "fields": [
    {"name": "Name", "type": "string"},
    {"name": "Age", "type": "int"}
  ]
}
```

This program handles basic cases but does not cover all possible scenarios, such as nested structs or complex data structures. If more advanced functionality is needed, additional logic might be required.

