```php
<?php

/**
 * Sorts an associative array based on the 'age' key in descending order if 'order' is 'desc', or ascending order otherwise.
 *
 * @param array $set An associative array where each item has keys 'name', 'address', and 'age'.
 * @param string $order Determines the sorting order: either 'asc' (ascending) or 'desc' (descending).
 * @return array A sorted version of the input array.
 */
function smart_sort_array($set, $order = 'asc') {
    // Check if the input is valid
    foreach ($set as $item) {
        if (!is_array($item)) {
            throw new InvalidArgumentException("Input must be an array.");
        }
        if (!isset($item['name'])) {
            throw new InvalidArgumentException("'name' key is missing from some items in the set.");
        }
        if (!isset($item['address'])) {
            throw new InvalidArgumentException("'address' key is missing from some items in the set.");
        }
        if (!isset($item['age'])) {
            throw new InvalidArgumentException("'age' key is missing from some items in the set.");
        }
    }

    usort($set, function ($a, $b) use ($order) {
        return $order === 'desc' ? $b['age'] - $a['age'] : $a['age'] - $b['age'];
    });

    return $set;
}

// Example usage:
$people = [
    ['name' => 'John Doe', 'address' => '123 Main St', 'age' => 45],
    ['name' => 'Jane Smith', 'address' => '456 Elm St', 'age' => 30],
    ['name' => 'Alice Johnson', 'address' => '789 Oak St', 'age' => 50]
];

try {
    $sorted_people_asc = smart_sort_array($people);
    echo "Sorted ASC:\n";
    print_r($sorted_people_asc);

    $sorted_people_desc = smart_sort_array($people, 'desc');
    echo "\nSorted DESC:\n";
    print_r($sorted_people_desc);
} catch (InvalidArgumentException $e) {
    echo "Error: " . $e->getMessage();
}
?>
```

### Explanation:

- **Parameters**: 
  - `$set`: The input array containing associative arrays with keys `'name'`, `'address'`, and `'age'`.
  - `$order`: A string indicating whether to sort in ascending (`'asc'`) or descending (`'desc'`) order.

- **Functionality**:
  - Checks if the input is an array and all required fields ('name', 'address', 'age') exist.
  - Uses `usort()` to sort the array based on the age field, comparing values in descending order if `$order` is `'desc'`.

- **Output**:
  - Prints both sorted arrays side by side for comparison.

This code will output two arrays after sorting the original `$people` array based on their ages in ascending and descending orders.

